package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** $doc */
public class ${kind}Plan {
    public void ${call}(@Val Plan plan, @RequestParam("user") String user, PlanRepository plans, SheetRepository sheets,
            PersonRepository people, Audit audit, Out<Plans> saved) throws InvalidPlanException {
        if ($cond) {
            throw new InvalidPlanException("$msg");
        }
        plans.${call}(plan, sheets.today(plan.sheetId()));
        Person person = people.find(plan.sheetId(), plan.personId());
        audit.record("$ev sheet=" + plan.sheetId() + " by=" + user + " name=" + person.name() + " start="
                + plan.start());
        saved.set(new Plans(java.util.List.of(plans.find(plan.sheetId(), plan.id()))));
    }
}
